1291	      FAR struct ifreq *ifr = (FAR struct ifreq *)arg;
1292	      if (priv == NULL || ifr == NULL)
1293	        {
1294	          return -EINVAL;
1295	        }
1296	
1297	      strlcpy(ifr->ifr_name, priv->dev.d_ifname, IFNAMSIZ);
1298	
1299	      return OK;
1300	    }
1301	  else if (cmd == TUNSETCARRIER)
1302	    {
1303	      if (priv == NULL || arg == 0)
1304	        {
1305	          return -EINVAL;
1306	        }
1307	
1308	      if (*(FAR int *)((uintptr_t)arg))
1309	        {
1310	          netdev_carrier_on(&priv->dev);
1311	        }
1312	      else
1313	        {
1314	          netdev_carrier_off(&priv->dev);
1315	        }
1316	
1317	      return OK;
1318	    }
1319	
1320	  return -ENOTTY;
1321	}
