884	static int tun_dev_init(FAR struct tun_device_s *priv,
885	                        FAR struct file *filep,
886	                        FAR const char *devfmt, bool tun)
887	{
888	  int ret;
889	
890	  /* Initialize the driver structure */
891	
892	  memset(priv, 0, sizeof(struct tun_device_s));
893	  priv->dev.d_ifup    = tun_ifup;     /* I/F up (new IP address) callback */
894	  priv->dev.d_ifdown  = tun_ifdown;   /* I/F down callback */
895	  priv->dev.d_txavail = tun_txavail;  /* New TX data callback */
896	#ifdef CONFIG_NET_MCASTGROUP
897	  priv->dev.d_addmac  = tun_addmac;   /* Add multicast MAC address */
898	  priv->dev.d_rmmac   = tun_rmmac;    /* Remove multicast MAC address */
899	#endif
900	  priv->dev.d_private = priv;         /* Used to recover private state from dev */
901	
902	  /* Initialize the mutual exlcusion and wait semaphore */
903	
904	  nxmutex_init(&priv->lock);
905	  spin_lock_init(&priv->spinlock);
906	  nxsem_init(&priv->read_wait_sem, 0, 0);
907	  nxsem_init(&priv->write_wait_sem, 0, 0);
908	
909	  /* Assign d_ifname if specified. */
910	
911	  if (devfmt)
912	    {
913	      strlcpy(priv->dev.d_ifname, devfmt, IFNAMSIZ);
914	    }
915	
916	  /* Register the device with the OS so that socket IOCTLs can be performed */
917	
918	  ret = netdev_register(&priv->dev, tun ? NET_LL_TUN : NET_LL_ETHERNET);
919	  if (ret != OK)
920	    {
921	      nxmutex_destroy(&priv->lock);
922	      nxsem_destroy(&priv->read_wait_sem);
923	      nxsem_destroy(&priv->write_wait_sem);
924	      return ret;
925	    }
926	
927	  filep->f_priv = priv; /* Set link to TUN device */
928	  return ret;
929	}
